// ======================================================
// START / STOP AFHANDELING
// ======================================================

// Verwacht invoer via inject / knop:
// - msg.payload === true  → START ON
// - msg.payload === false → START OFF (harde reset)
const run = msg.payload;

// Helper voor tekstuele logging (STATUS output – output 4)
function status(txt) {
  node.send([null, null, null, { payload: txt }]);
}

// ------------------------------------------------------
// START OFF = HARD RESET VAN HET HELE SYSTEEM
// ------------------------------------------------------
if (run === false) {

  // Markeer systeem als niet draaiend
  context.set('running', false);

  // Stop eventuele countdown-intervals
  const ct = context.get('cd');
  if (ct) clearInterval(ct);

  // ✅ Reset klasse-nummer zodat nieuwe START weer bij 1 begint
  context.set('classNumber', 0);

  // Zet ALLE outputs expliciet naar 0 (veilig!)
  node.send([
    { payload: { outputs: { oranje_vlag: 0 } } }, // vlag neer
    { payload: { outputs: { hoorn: 0 } } },       // hoorn uit
    { payload: { outputs: { piezo: 0 } } },       // piezo uit
    { payload: 'START OFF – HARD RESET' }          // statusmelding
  ]);

  // Geen verdere logica uitvoeren
  return null;
}

// ------------------------------------------------------
// Voorkom dubbel starten (START ON terwijl al actief)
// ------------------------------------------------------
if (run !== true || context.get('running')) return null;

// Markeer systeem als actief
context.set('running', true);


// ======================================================
// CONFIGURATIE (tijden in ms – verkort voor debug)
// ======================================================
const ORANGE_TIME = 20 * 100;      // Oranje vlag fase
const T5 = 5 * 60 * 100;           // Startcyclusduur
const T4 = 4 * 60 * 100;           // 4 min vóór start
const T1 = 1 * 60 * 100;           // 1 min vóór start
const PIEZO_BEFORE = 10 * 1000;    // 10 s vóór start

const HORN_SHORT = 500;            // Korte toeter
const HORN_LONG  = 2000;           // Lange toeter (START)


// ======================================================
// HELPERS VOOR OUTPUT-AANSTURING
// ======================================================

// Stuurt een hoornpuls (kort of lang)
// label wordt alleen gebruikt voor logging
function horn(ms, label) {

  // Log waarom de hoorn klinkt
  status(`HOORN - ${label}`);

  // Hoorn AAN
  node.send([null, { payload: { outputs: { hoorn: 1 } } }, null, null]);

  // Hoorn UIT na ms
  setTimeout(() => {
    if (!context.get('running')) return;
    node.send([null, { payload: { outputs: { hoorn: 0 } } }, null, null]);
  }, ms);
}

// Stuurt piezo AAN of UIT
// Het knipperen gebeurt in de PIEZO BLINKER node
function piezo(on) {
  status(`PIEZO - ${on ? 'AAN (laatste 10s)' : 'UIT'}`);
  node.send([
    null,
    null,
    { payload: { outputs: { piezo: on ? 1 : 0 } } },
    null
  ]);
}


// ======================================================
// ORANJE VLAG FASE (VOORSTART)
// ======================================================

// Oranje vlag OP bij START ON
node.send([
  { payload: { outputs: { oranje_vlag: 1 } } },
  null,
  null,
  null
]);

status('START ON – ORANJE VLAG OP');

// Na ORANGE_TIME:
// - vlag AF
// - éénmalige korte toeter
// - start eerste klasse
setTimeout(() => {

  if (!context.get('running')) return;

  // Oranje vlag neer
  node.send([
    { payload: { outputs: { oranje_vlag: 0 } } },
    null,
    null,
    null
  ]);

  // Eénmalige attentietoeter bij vlag AF
  horn(HORN_SHORT, 'VLAG AF (EENMALIG)');

  // Start eerste klassecyclus
  startClass();

}, ORANGE_TIME);


// ======================================================
// KLASSE CYCLUS (HERHAALT ONEINDIG PER KLASSE)
// ======================================================
function startClass() {

  // Bepaal volgend klasse-nummer
  let classNumber = (context.get('classNumber') || 0) + 1;
  context.set('classNumber', classNumber);

  status(`KLASSE ${classNumber} START CYCLUS`);

  // 4 minuten vóór start → korte toeter
  setTimeout(() => {
    if (context.get('running')) horn(HORN_SHORT, '4 MIN');
  }, T5 - T4);

  // 1 minuut vóór start → korte toeter
  setTimeout(() => {
    if (context.get('running')) horn(HORN_SHORT, '1 MIN');
  }, T5 - T1);

  // 10 seconden vóór start → piezo aan
  setTimeout(() => {
    if (context.get('running')) piezo(true);
  }, T5 - PIEZO_BEFORE);

  // START MOMENT:
  // - piezo uit
  // - lange toeter
  // - start volgende klasse
  setTimeout(() => {

    if (!context.get('running')) return;

    piezo(false);
    horn(HORN_LONG, 'START');

    // Volgende klasse
    startClass();

  }, T5);
}

return null;

// ================= CONFIG =================
const ON_TIME  = 250;  // ms
const OFF_TIME = 750;  // ms

// ================= STATE ==================
let timer = context.get('timer') || null;
let active = context.get('active') || false;

// ================= HELPERS =================
function send(val) {
    node.send({
        payload: {
            outputs: {
                piezo: val
            }
        }
    });
}

function stopBlinking() {
    active = false;
    context.set('active', false);

    if (timer !== null) {
        clearTimeout(timer);
        timer = null;
        context.set('timer', null);
    }

    // Forceer UIT
    send(0);
}

// ================= DEPLOY / CLOSE =================
node.on('close', function () {
    stopBlinking();
});

// ================= LOGIC =================
const cmd = msg && msg.payload && msg.payload.outputs
    ? msg.payload.outputs.piezo
    : undefined;

// START knipperen
if (cmd === 1 && !active) {
    active = true;
    context.set('active', true);

    function loop() {
        if (!context.get('active')) return;

        // AAN
        send(1);

        timer = setTimeout(() => {
            if (!context.get('active')) return;

            // UIT
            send(0);

            timer = setTimeout(() => {
                loop();
            }, OFF_TIME);

            context.set('timer', timer);
        }, ON_TIME);

        context.set('timer', timer);
    }

    loop();
    return null;
}

// STOP knipperen
if (cmd === 0) {
    stopBlinking();
    return null;
}

// Andere berichten negeren
return null;

// Manual hoorn HOLD (drukken = aan, loslaten = uit)

const on = msg.payload === true;

node.send({
  payload: {
    outputs: {
      hoorn: on ? 1 : 0
    }
  }
});

return null;
